 page.locator('#role-select').select_option('maria');page.goto(BASE+'/#member-pranav');page.locator('#consent-withdrawn').check();expect(page.locator('#banner')).to_contain_text('Clinical details hidden');page.locator('[data-jump=evidence]').click();assert 'Current safety' not in page.locator('.ev').inner_text();page.locator('[data-src=BH-004A]').count() if False else None
