 page.locator('[data-extra=closure]').click();expect(page.locator('[data-extra=close-case]')).to_be_disabled();expect(page.locator('#dlg')).to_contain_text('No CM receipt');page.locator('[data-act=close]').click();checks.append('closure blocked until evidence and review')
